func (s *ManualCommitStrategy) PostCommit(ctx context.Context) error { //nolint:unparam // error return is part of the hook contract; callers check it
	logCtx := logging.WithComponent(ctx, "checkpoint")

	_, openRepoSpan := perf.Start(ctx, "open_repository_and_head")
	repo, err := OpenRepository(ctx)
	if err != nil {
		openRepoSpan.RecordError(err)
		openRepoSpan.End()
		return nil
	}

	// Get HEAD commit to check for trailer
	head, err := repo.Head()
	if err != nil {
		openRepoSpan.RecordError(err)
		openRepoSpan.End()
		return nil
	}

	commit, err := repo.CommitObject(head.Hash())
	if err != nil {
		openRepoSpan.RecordError(err)
		openRepoSpan.End()
		return nil
	}

	// Check if commit has checkpoint trailer (ParseCheckpoint validates format)
	checkpointID, found := trailers.ParseCheckpoint(commit.Message)
	openRepoSpan.End()

	if !found {
		// No trailer — user removed it or it was never added (mid-turn commit).
		// Still update BaseCommit for active sessions so future commits can match.
		s.postCommitUpdateBaseCommitOnly(ctx, head)
		return nil
	}

	_, findSessionsSpan := perf.Start(ctx, "find_sessions_from_shadow_tree")
	worktreePath, err := paths.WorktreeRoot(ctx)
	if err != nil {
		findSessionsSpan.RecordError(err)
		findSessionsSpan.End()
		return nil
	}

	// Use shadow-tree-based session discovery: only load sessions whose
	// BaseCommit == parent of HEAD (i.e., sessions on the current shadow branch).
	// Sessions from different base commits are structurally irrelevant — their
	// ENDED BaseCommit is frozen, so they belong to a different checkpoint epoch.
	// This gives O(1) PostCommit in git ref lookups regardless of total accumulated
	// session count; the state file scan is cheap JSON-only (no git operations).
	parentHash := ""
	if commit.NumParents() > 0 {
		if parent, pErr := commit.Parent(0); pErr == nil {
			parentHash = parent.Hash.String()
		}
	}
	sessions, err := s.findSessionsFromShadowTree(ctx, repo, parentHash, worktreePath)
	findSessionsSpan.RecordError(err)
	findSessionsSpan.End()

	if err != nil || len(sessions) == 0 {
		logging.Warn(logCtx, "post-commit: no active sessions despite trailer",
			slog.String("strategy", "manual-commit"),
			slog.String("checkpoint_id", checkpointID.String()),
		)
		return nil //nolint:nilerr // Intentional: hooks must be silent on failure
	}

	// Build transition context
	isRebase := isGitSequenceOperation(ctx)

