// TestCarryForward_EndedSession_OnlyCondensingOnOverlap verifies that an ENDED
// session with carry-forward files is condensed only when those files are actually
// committed, not when unrelated files are committed (GitHub issue #591).
//
// The fix for issue #591 is eager-condense-on-stop (CondenseAndMarkFullyCondensed):
// sessions with NO FilesTouched at stop time are marked FullyCondensed immediately
// and skipped on all future commits. Sessions with FilesTouched at stop time wait
// for those files to be committed, then condense and mark FullyCondensed.
//
// Scenario:
// 1. Session 1 creates file1.txt and file2.txt
// 2. User commits only file1.txt (partial commit) — session 1 gets carry-forward
// 3. Session 1 ends (FilesTouched = ["file2.txt"])
// 4. Session 2 commits unrelated file6.txt — session 1 NOT condensed (no overlap)
// 5. User commits file2.txt — session 1 IS condensed and marked FullyCondensed
func TestCarryForward_EndedSession_OnlyCondensingOnOverlap(t *testing.T) {
	t.Parallel()
	env := NewTestEnv(t)
	defer env.Cleanup()

	// ========================================
	// Setup
	// ========================================
	env.InitRepo()
	env.WriteFile("README.md", "# Test Repository")
	env.GitAdd("README.md")
	env.GitCommit("Initial commit")
	env.GitCheckoutNewBranch("feature/multi-session-carry-forward")
	env.InitEntire()

	// ========================================
	// Phase 1: Session 1 creates files, partial commit, ends with carry-forward
	// ========================================
	t.Log("Phase 1: Session 1 creates file1.txt and file2.txt")

	session1 := env.NewSession()
